const paths={arrow:'M4 12h16m-6-6 6 6-6 6',pin:'M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',phone:'M7 3H4a1 1 0 0 0-1 1c0 9.4 7.6 17 17 17a1 1 0 0 0 1-1v-3l-5-2-2 2a15 15 0 0 1-7-7l2-2-2-5Z',mail:'M3 5h18v14H3ZM3 5l9 8 9-8',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Zm-4 9 3 3 5-6',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm8-7.87a4 4 0 0 1 0 7.75',compass:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM16 8l-3 5-5 3 3-5 5-3Z',check:'M5 12l4 4L19 6',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM12 6v6l4 2',sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5M17.5 17.5 19 19M5 19l1.5-1.5M17.5 6.5 19 5',briefcase:'M3 7h18v14H3ZM8 7V3h8v4M3 12c5 4 13 4 18 0m-9 1v3',menu:'M4 6h16M4 12h16M4 18h16',print:'M6 9V3h12v6M6 18H3V9h18v9h-3M6 14h12v7H6Z'};
const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.compass}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tidy=s=>String(s).replace(/[\p{Extended_Pictographic}\uFE0F]/gu,'').trim();
const tripUrl=t=>`#wycieczka/${t.id}`;
const summaries={
 'staszow-fabryka-bombek-i-magia-swiatecznego-szkla':['Staszów','Fabryka bombek i magia świątecznego szkła'],
 'lodz-wroclaw-od-farbyki-do-krasnala-5-dni':['Łódź i Wrocław','Od fabryki do krasnala'],
 'kopernik-krzyzacy-i-baltyk-torun-malbork-trojmiasto':['Toruń, Malbork, Trójmiasto','Kopernik, Krzyżacy i Bałtyk'],
 'bochnia-nowy-wisnicz-w-podziemnej-krainie-czarow':['Bochnia i Nowy Wiśnicz','W podziemnej krainie czarów'],
 'energylandia-festiwal-rozrywki':['Energylandia','Festiwal rozrywki'],
 'budapeszt-zakole-dunaju':['Budapeszt i Zakole Dunaju','Odkryj Budapeszt i malownicze okolice'],
 'sandomierz-baranow-sandomierski-perla-renesansu':['Sandomierz i Baranów Sandomierski','Perła Renesansu'],
 'warszawa-perelki-stolicy':['Warszawa','Perełki stolicy'],
 'krakow-dla-najmlodszych-szlakiem-legend':['Kraków dla najmłodszych','Szlakiem legend']
};
const header=()=>`<a class="skip-link" href="#main">Przejdź do treści</a><div class="topbar"><div class="wrap"><span class="location-note">${icon('pin')} Twoje biuro podróży w sercu Rzeszowa</span><span><a href="tel:+48503155923">${icon('phone')}+48 503 155 923</a><a href="mailto:traper@traper.com.pl">${icon('mail')}traper@traper.com.pl</a></span></div></div><header class="nav"><div class="wrap nav-inner"><a class="logo" href="#" aria-label="TRAPER — strona główna"><img src="assets/logo.png" alt="TRAPER" width="118" height="74"></a><button class="menu-toggle" aria-controls="navigation" aria-expanded="false">Menu ${icon('menu')}</button><nav id="navigation" class="nav-links" aria-label="Menu główne"><a href="#wycieczki">Wycieczki szkolne</a><a href="#wypoczynek">Kolonie i wypoczynek</a><a href="#dla-firm">Dla firm</a><a href="#o-nas">O nas</a><a href="#kontakt">Kontakt</a><a class="btn small" href="#kontakt">Zaplanuj wyjazd ${icon('arrow')}</a></nav></div></header>`;
const footer=()=>`<footer class="footer"><div class="wrap"><span>© ${new Date().getFullYear()} TRAPER · Biuro Turystyczno-Usługowe</span><div class="footer-links"><a href="https://traper.com.pl/dokumenty/" target="_blank" rel="noopener">Dokumenty na traper.com.pl</a><a href="https://traper.com.pl/polityka-prywatnosci/" target="_blank" rel="noopener">Polityka prywatności</a><a href="#kontakt">Kontakt</a></div></div></footer>`;
function contact(){return `<section id="kontakt" class="contact"><div class="wrap contact-grid"><div class="contact-copy"><p class="eyebrow">Porozmawiajmy o Twoim wyjeździe</p><h2>Twoja grupa.<br>Wasza kolejna przygoda.</h2><p>Masz pytania dotyczące wycieczki? Napisz do nas – chętnie przygotujemy ofertę dopasowaną do Twoich potrzeb.</p><div class="contact-list"><div class="contact-row">${icon('phone')}<div><a href="tel:+48503155923"><strong>+48 503 155 923</strong></a><a href="tel:+48509456065"><span>+48 509 456 065</span></a></div></div><div class="contact-row">${icon('mail')}<div><a href="mailto:traper@traper.com.pl"><strong>traper@traper.com.pl</strong></a></div></div><div class="contact-row">${icon('pin')}<div><strong>ul. Słowackiego 11, Rzeszów</strong><span>35-060 Rzeszów · pon.–pt. 9:00–16:00</span></div></div></div><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=Traper%20S%C5%82owackiego%2011%20Rzesz%C3%B3w" target="_blank" rel="noopener">Sprawdź dojazd ${icon('arrow')}</a></div><form class="contact-form" id="enquiry"><h3>Zaplanuj wyjazd z TRAPEREM</h3><p>Wybierz kierunek lub opowiedz nam o swoim pomyśle.</p><div class="form-grid"><label class="form-field">Imię i nazwisko *<input name="name" required autocomplete="name" placeholder="Jak się nazywasz?"></label><label class="form-field">Szkoła / firma<input name="organisation" autocomplete="organization" placeholder="Nazwa organizacji"></label><label class="form-field">Liczba uczestników<input name="participants" placeholder="Np. 40 + 3 opiekunów"></label><label class="form-field">Planowany termin<input name="date" placeholder="Np. maj 2027"></label><label class="form-field full">Kierunek lub wycieczka<select name="trip"><option value="">Jeszcze nie wiem — szukam inspiracji</option>${TRIPS.map(t=>`<option value="${esc(summaries[t.id][0])}">${esc(summaries[t.id][0])}</option>`).join('')}<option>Inny kierunek / własny pomysł</option></select></label><label class="form-field full">Opowiedz nam więcej<textarea name="message" placeholder="Wiek uczestników, liczba dni, pomysł na wyjazd…"></textarea></label></div><button class="btn" type="submit">Przygotuj e-mail z zapytaniem ${icon('arrow')}</button><p class="form-note">Otworzymy Twoją aplikację pocztową z przygotowaną wiadomością. Wyślesz ją samodzielnie na traper@traper.com.pl.</p></form></div></section>`}
function card(t){const [title,subtitle]=summaries[t.id];return `<article class="trip-card"><a href="${tripUrl(t)}" class="card-image" tabindex="-1" aria-hidden="true"><img src="${t.image}" alt="${esc(title)}" loading="lazy" width="800" height="600"><span class="badge">${esc(t.country)}</span></a><div class="card-content"><div class="card-meta">${icon('users')} Wycieczka szkolna${t.days?` <span>·</span> ${t.days===1?'1 dzień':t.days+' dni'}`:''}</div><h3><a href="${tripUrl(t)}">${esc(title)}</a></h3><p class="card-subtitle">${esc(subtitle)}</p></div><div class="card-footer"><span>Oferta dla grup</span><a href="${tripUrl(t)}" aria-label="Zobacz program: ${esc(title)}"><strong>Zobacz program</strong>${icon('arrow')}</a></div></article>`}
let activeCategory='all',activeDuration='all',showAll=false;
function updateCards(){const list=TRIPS.filter(t=>(activeCategory==='all'||t.category===activeCategory)&&(activeDuration==='all'||String(t.days)===activeDuration));const order=[2,5,1,8,3,7,0,4,6].map(i=>TRIPS[i]);const sorted=order.filter(t=>list.includes(t));document.getElementById('cards').innerHTML=sorted.length?sorted.slice(0,showAll?99:6).map(card).join(''):'<p class="empty">Nie ma wycieczek z takim połączeniem filtrów. Zmień wybór lub zapytaj nas o indywidualny program.</p>';const b=document.getElementById('show-more');b.hidden=showAll||sorted.length<=6;document.getElementById('offer-count').textContent=`${sorted.length} ${sorted.length===1?'propozycja':sorted.length<5?'propozycje':'propozycji'} wyjazdu`;}
function home(){activeCategory='all';activeDuration='all';showAll=false;document.title='TRAPER — Biuro podróży Rzeszów';document.getElementById('app').innerHTML=header()+`<main id="main"><section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><p class="eyebrow line">Rzeszów · Polska · Europa</p><h1>Żyj marzeniami,<br><em>podróżuj z nami.</em></h1><p>Organizujemy niezapomniane wycieczki szkolne i firmowe. Ponad 30 lat doświadczenia w branży turystycznej.</p><div class="actions"><a class="btn" href="#wycieczki">Odkryj nasze wycieczki ${icon('arrow')}</a><a class="btn secondary" href="#kontakt">Zaplanuj wyjazd</a></div><div class="hero-proof">${icon('shield')} Sprawdzona organizacja. Opieka na każdym etapie.</div></div><div class="hero-image"><img src="assets/hero.jpg" alt="Pałac i ogrody — zdjęcie z podróży TRAPERA" width="1592" height="1194" fetchpriority="high"><div class="photo-note"><div class="icon-box">${icon('compass')}</div><div><strong>Blisko i daleko. Zawsze razem.</strong><span>Wycieczki w Polsce i za granicą</span></div></div></div></div></section><div class="trust-strip"><div class="wrap trust-grid"><div class="trust-item">${icon('users')} Programy dopasowane do grupy</div><div class="trust-item">${icon('shield')} Doświadczeni piloci i opieka</div><div class="trust-item">${icon('check')} Minimum formalności dla organizatora</div></div></div><section class="section" id="wycieczki"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Dokąd tym razem?</p><h2>Małe wyprawy. Wielkie wspomnienia.</h2><p>Wybierz jedną z naszych sprawdzonych propozycji lub powiedz nam o swoim pomyśle na wyjazd.</p></div><a class="text-link" href="#kontakt">Wyjazd na zamówienie ${icon('arrow')}</a></div><div class="filters" aria-label="Filtruj wycieczki"><button class="filter active" data-category="all" aria-pressed="true">Wszystkie wycieczki</button><button class="filter" data-category="Krajowe" aria-pressed="false">Polska</button><button class="filter" data-category="Zagraniczne" aria-pressed="false">Zagranica</button><select class="filter-select" id="duration" aria-label="Liczba dni"><option value="all">Dowolna długość wyjazdu</option value="1">1 dzień</option><option value="5">5 dni</option></select></div><div class="cards" id="cards"></div><div class="offer-foot"><span id="offer-count" role="status"></span><button id="show-more" class="btn secondary">Zobacz więcej wycieczek ${icon('arrow')}</button></div><div class="custom-banner"><div><h3>Masz grupę, ale jeszcze nie masz kierunku?</h3><p>Nie znalazłeś idealnej oferty? Przygotujemy ją specjalnie dla Ciebie! Dopasujemy wyjazd do Twoich oczekiwań – w Polsce lub w Europie.</p></div><a class="btn" href="#kontakt">Porozmawiajmy ${icon('arrow')}</a></div></div></section><section class="section more-travel" id="wypoczynek"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Więcej możliwości z TRAPEREM</p><h2>Każdy ma swój sposób na podróż.</h2></div></div><div class="more-grid"><article class="more-card">${icon('sun')}<h3>Kolonie i obozy</h3><p>Wypoczynek dla dzieci i młodzieży: kolonie, obozy, zimowiska oraz zielone szkoły.</p><a class="text-link" href="https://traper.com.pl/oferta/kolonie-obozy/" target="_blank" rel="noopener">Oferta na traper.com.pl ${icon('arrow')}</a></article><article class="more-card" id="dla-firm">${icon('briefcase')}<h3>Wyjazdy dla firm</h3><p>Wyjazdy firmowe, szkolenia i konferencje. Transport, zakwaterowanie, wyżywienie i atrakcje dodatkowe.</p><a class="text-link" href="https://traper.com.pl/oferta/wycieczki-dla-firm/" target="_blank" rel="noopener">Oferta na traper.com.pl ${icon('arrow')}</a></article><article class="more-card">${icon('compass')}<h3>Wczasy i sanatoria</h3><p>Wczasy letnie i zimowe w kraju i za granicą oraz pobyty sanatoryjne.</p><a class="text-link" href="https://traper.com.pl/oferta/wczasy-krajowe-zagraniczne/" target="_blank" rel="noopener">Wczasy ${icon('arrow')}</a><span> · </span><a class="text-link" href="https://traper.com.pl/oferta/pobyty-sanatoryjne/" target="_blank" rel="noopener">Sanatoria ${icon('arrow')}</a></article></div></div></section><section class="section" id="o-nas"><div class="wrap about-grid"><div class="about-photo"><img src="assets/about.jpg" alt="Krupówki w Zakopanem o zmierzchu" loading="lazy" width="1688" height="1125"><div class="experience"><strong>30+</strong><span>lat doświadczenia<br>w organizacji podróży</span></div></div><div class="about-copy"><p class="eyebrow">Poznaj biuro podróży TRAPER</p><h2>Z nami każda podróż<br>to przygoda.</h2><p>Od ponad 30 lat tworzymy niezapomniane wyjazdy w kraju i za granicą. Nasze doświadczenie, sprawdzona organizacja oraz dbałość o każdy szczegół sprawiają, że zaufało nam już wielu klientów – a wielu z nich wraca do nas regularnie, planując kolejne podróże.</p><div class="benefits"><div class="benefit">${icon('check')}Programy dopasowane do wieku i potrzeb grupy</div><div class="benefit">${icon('check')}Sprawdzeni piloci i organizacja wyjazdów</div><div class="benefit">${icon('check')}Bezpieczeństwo i opieka na każdym etapie</div></div><a class="text-link" href="https://traper.com.pl/referencje/" target="_blank" rel="noopener">Zobacz referencje naszych klientów ${icon('arrow')}</a></div></div></section><section class="steps-section"><div class="wrap"><p class="eyebrow">Od pomysłu do wyjazdu</p><h2>Ty wybierasz kierunek. My dbamy o resztę.</h2><div class="steps"><article class="step"><span class="step-number">01 / POMYSŁ</span><h3>Wybór kierunku</h3><p>Wybierz jedną z naszych propozycji lub powiedz nam o swoim pomyśle na wyjazd.</p></article><article class="step"><span class="step-number">02 / PLAN</span><h3>Przygotowanie oferty</h3><p>Przygotujemy szczegółowy program wycieczki wraz z przejrzystą wyceną.</p></article><article class="step"><span class="step-number">03 / ORGANIZACJA</span><h3>Dopełnienie formalności</h3><p>Podpisujemy umowę i dostarczamy dokumenty potrzebne do organizacji wycieczki.</p></article><article class="step"><span class="step-number">04 / PRZYGODA</span><h3>Realizacja wycieczki</h3><p>Podczas wyjazdu opiekę nad grupą sprawuje nasz doświadczony pilot.</p></article></div></div></section><section class="section"><div class="wrap faq-grid"><div><p class="eyebrow">Dobrze wiedzieć przed wyjazdem</p><h2>O co najczęściej pytacie?</h2><p>Planujesz wycieczkę po raz pierwszy? Chętnie odpowiemy na Twoje pytania.</p><a class="text-link" href="#kontakt">Zapytaj nas ${icon('arrow')}</a></div><div><details><summary>Czy można zmodyfikować program wycieczki?</summary><p>Tak. Możemy wzbogacić program o konkretne warsztaty, odwiedzić dodatkowe miejsce lub dostosować tempo wyjazdu do wieku uczniów.</p></details><details><summary>Jakie formalności musi dopełnić nauczyciel?</summary><p>Przygotowujemy wzory dokumentów: umowę, regulamin wycieczki, listę uczestników oraz szczegółowy program. Nauczyciel zbiera podpisy od rodziców i dostarcza finalną listę uczestników.</p></details><details><summary>Czy cena wycieczki obejmuje ubezpieczenie?</summary><p>Wycieczki organizowane przez Biuro Podróży TRAPER zawierają ubezpieczenie NNW dla uczestników oraz opiekunów. Zakres świadczeń znajdziesz w programie i przygotowanej ofercie.</p></details><details><summary>Co z wyżywieniem i noclegiem?</summary><p>Współpracujemy ze sprawdzonymi obiektami noclegowymi, które goszczą grupy szkolne. Posiłki są dostosowane do potrzeb dzieci i młodzieży.</p></details></div></div></section></main>`+contact()+footer();
 updateCards();document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{activeCategory=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b?'true':'false')});showAll=false;updateCards()}));document.getElementById('duration').addEventListener('change',e=>{activeDuration=e.target.value;showAll=false;updateCards()});document.getElementById('show-more').addEventListener('click',()=>{showAll=true;updateCards()});bind();}
function articleBlocks(blocks){let html='',list=false;for(const b of blocks){if(b.type==='li'){if(!list){html+='<ul>';list=true}html+=`<li>${esc(tidy(b.text))}</li>`;}else{if(list){html+='</ul>';list=false}html+=`<${b.type}>${esc(tidy(b.text))}</${b.type}>`;}}return html+(list?'</ul>':'')}
function detail(t){const [title,subtitle]=summaries[t.id];document.title=title+' — wycieczka z TRAPEREM';const blocks=(t.blocks||[]).slice(1);const program=blocks.findIndex(b=>b.text.trim()==='Program');const leading=program>=0?blocks.slice(0,program):blocks;const programBlocks=program>=0?blocks.slice(program):[];document.getElementById('app').innerHTML=header()+`<main id="main"><section class="detail-hero"><div class="wrap"><div class="breadcrumbs"><a href="#">Strona główna</a> / <a href="#wycieczki">Wycieczki szkolne</a> / ${esc(title)}</div><div class="detail-intro"><div><p class="eyebrow">Wycieczki szkolne · ${esc(t.country)}</p><h1>${esc(title)}</h1><p style="margin-top:15px">${esc(subtitle)}</p><div class="card-meta">${icon('users')} Oferta dla grup${t.days?` · ${t.days===1?'1 dzień':t.days+' dni'}`:''}</div><div class="actions"><a class="btn" href="#kontakt" data-trip="${esc(title)}">Zapytaj o tę wycieczkę ${icon('arrow')}</a><button class="btn secondary" id="print-program">${icon('print')}Drukuj program</button></div></div><img src="${t.image}" alt="${esc(title)}" width="800" height="600"></div></div></section><section class="section"><div class="wrap detail-body"><article class="article"><div class="detail-note">Program możemy dostosować do potrzeb Twojej grupy. Zapytaj o termin i indywidualną wycenę.</div>${articleBlocks(leading)}${articleBlocks(programBlocks)}<p class="print-only">Biuro Turystyczno-Usługowe TRAPER Karolina Borowiec · ul. Słowackiego 11, 35-060 Rzeszów · +48 503 155 923 · traper@traper.com.pl</p></article><aside class="enquiry-aside"><p class="eyebrow">Wyrusz z TRAPEREM</p><h3>Zaplanuj wyjazd dla swojej grupy</h3><p>Podaj nam liczbę uczestników i planowany termin. Przygotujemy ofertę dopasowaną do Twoich potrzeb.</p><a href="#kontakt" data-trip="${esc(title)}" class="btn">Zapytaj o ofertę ${icon('arrow')}</a><span>Wolisz porozmawiać?</span><a href="tel:+48503155923">+48 503 155 923</a><p>Poniedziałek–piątek<br>9:00–16:00</p><a class="text-link" style="font-size:12px;font-weight:500" href="${esc(t.source)}" target="_blank" rel="noopener">Oferta na traper.com.pl ${icon('arrow')}</a></aside></div></section></main>`+contact()+footer();bind();document.querySelector('#print-program').addEventListener('click',()=>window.print());const select=document.querySelector('[name=trip]');select.value=title;window.scrollTo(0,0);}
function bind(){const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('.nav-links');toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open))});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');toggle.setAttribute('aria-expanded','false')}));document.querySelectorAll('[data-trip]').forEach(a=>a.addEventListener('click',()=>{sessionStorage.setItem('traper-enquiry',a.dataset.trip)}));document.getElementById('enquiry').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);const body=`Dzień dobry,\n\nProszę o przygotowanie oferty wyjazdu.\n\nImię i nazwisko: ${d.get('name')}\nSzkoła / firma: ${d.get('organisation')}\nLiczba uczestników: ${d.get('participants')}\nPlanowany termin: ${d.get('date')}\nKierunek: ${d.get('trip')||'Proszę o propozycję kierunku'}\n\n${d.get('message')}\n\nPozdrawiam,\n${d.get('name')}`;window.location.href='mailto:traper@traper.com.pl?subject='+encodeURIComponent('Zapytanie o wyjazd — '+(d.get('trip')||'oferta dla grupy'))+'&body='+encodeURIComponent(body)});}
function route(){const hash=location.hash;if(hash.startsWith('#wycieczka/')){const id=hash.slice(11),t=TRIPS.find(t=>t.id===id);if(t){detail(t);return}}if(!document.getElementById('cards'))home();const target=hash?document.getElementById(hash.slice(1)):null;if(target){target.scrollIntoView();if(hash==='#kontakt'){const selected=sessionStorage.getItem('traper-enquiry');if(selected){document.querySelector('[name=trip]').value=selected;sessionStorage.removeItem('traper-enquiry')}}}else if(!hash)window.scrollTo(0,0);}
window.addEventListener('hashchange',route);route();
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const tool={name:'find_traper_trips',title:'Znajdź wycieczki TRAPER',description:'Read the tour catalogue and match a country or destination. Does not send an enquiry or book a trip.',inputSchema:{type:'object',properties:{query:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>k!=='query')||(input.query!==undefined&&typeof input.query!=='string'))throw new Error('Expected an optional text query.');const q=(input.query||'').toLocaleLowerCase('pl');return TRIPS.filter(t=>(t.title+' '+t.country).toLocaleLowerCase('pl').includes(q)).map(t=>({title:summaries[t.id][0],country:t.country,days:t.days,url:tripUrl(t)}));}};
 try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
